def _run_full_engine_extracted_3_apply_combination(
    _interaction: Any,
    transformed_branches: TransformedBranches,
    chart_branches: list[str | None],
) -> None:
    _el = _interaction.resultant_element
    if not _el:
        return
    for _b in _interaction.actors:
        if transformed_branches.has_state(_b, chart_branches):
            continue
        transformed_branches.set_branch_state(_b, _el, chart_branches)

def _run_full_engine_extracted_3_apply_clash(
    _interaction: Any,
    transformed_branches: TransformedBranches,
    chart_branches: list[str | None],
) -> None:
    for _b in _interaction.actors:
        if transformed_branches.has_state(_b, chart_branches):
            continue
        transformed_branches.set_branch_state(_b, "UNSTABLE", chart_branches)

def _run_full_engine_extracted_3_process_interaction(
    _interaction: Any,
    transformed_branches: TransformedBranches,
    chart_branches: list[str | None],
) -> None:
    if _interaction.vector in ("SanHe", "SanHui", "BanHe", "LiuHe", "WuHe") and _interaction.is_successful:
        _run_full_engine_extracted_3_apply_combination(_interaction, transformed_branches, chart_branches)
        return

